const BUILDER_URL="builder.html?v=4.5.12";
const DEFAULT_RULES_DATA="data:application/pdf;base64,";
const RULES_DB="armiesBuilderFiles", RULES_STORE="files";
function rulesDb(){return new Promise((resolve,reject)=>{const r=indexedDB.open(RULES_DB,1);r.onupgradeneeded=()=>r.result.createObjectStore(RULES_STORE);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function rulesGet(){const db=await rulesDb();return new Promise((resolve,reject)=>{const r=db.transaction(RULES_STORE).objectStore(RULES_STORE).get('rules');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function rulesSet(v){const db=await rulesDb();return new Promise((resolve,reject)=>{const r=db.transaction(RULES_STORE,'readwrite').objectStore(RULES_STORE).put(v,'rules');r.onsuccess=()=>resolve();r.onerror=()=>reject(r.error)})}
async function rulesDelete(){const db=await rulesDb();return new Promise((resolve,reject)=>{const r=db.transaction(RULES_STORE,'readwrite').objectStore(RULES_STORE).delete('rules');r.onsuccess=()=>resolve();r.onerror=()=>reject(r.error)})}
let rulesObjectUrl='';
async function showRules(){const saved=await rulesGet().catch(()=>null);if(rulesObjectUrl)URL.revokeObjectURL(rulesObjectUrl);if(saved?.blob){rulesObjectUrl=URL.createObjectURL(saved.blob);document.getElementById('rulesViewer').src=rulesObjectUrl}else document.getElementById('rulesViewer').src=DEFAULT_RULES_DATA;document.getElementById('rulesLayer').classList.add('open')}
const layer=document.getElementById('builderLayer');
const frame=document.getElementById('builderFrame');
document.querySelectorAll('[data-open-builder]').forEach(a=>a.onclick=e=>{e.preventDefault();frame.src=BUILDER_URL;layer.classList.add('open')});
document.getElementById('closeBuilder').onclick=()=>layer.classList.remove('open');
window.addEventListener('message',e=>{if(e.data==='armies-home'){layer.classList.remove('open');document.getElementById('rulesLayer')?.classList.remove('open');document.getElementById('exportLayer')?.classList.remove('open');document.getElementById('simpleModal')?.classList.remove('open')}});
document.getElementById('headerRules').onclick=e=>{e.preventDefault();showRules()}; document.getElementById('headerExport').onclick=e=>{e.preventDefault();document.getElementById('exportLayer').classList.add('open')}; document.querySelectorAll('[data-open-mydecks]').forEach(a=>a.onclick=e=>{e.preventDefault();frame.src=BUILDER_URL;layer.classList.add('open');frame.onload=()=>frame.contentWindow?.postMessage('armies-open-decks','*')}); document.querySelectorAll('[data-placeholder]').forEach(a=>a.onclick=e=>{e.preventDefault();const section=a.dataset.placeholder;if(section==='Regole Armies'){showRules();return}if(section==='Stampa ed esporta'){document.getElementById('exportLayer').classList.add('open');return}document.getElementById('modalTitle').textContent=section;document.getElementById('simpleModal').classList.add('open')});
document.getElementById('closeModal').onclick=()=>document.getElementById('simpleModal').classList.remove('open');
document.getElementById('closeRules').onclick=()=>document.getElementById('rulesLayer').classList.remove('open');
document.getElementById('closeExportInfo').onclick=()=>document.getElementById('exportLayer').classList.remove('open');
document.getElementById('openBuilderFromExport').onclick=()=>{document.getElementById('exportLayer').classList.remove('open');frame.src=BUILDER_URL;layer.classList.add('open')};
document.getElementById('rulesImport').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;if(!(file.type==='application/pdf'||file.type.startsWith('image/'))){alert('Seleziona un PDF o una immagine.');return}await rulesSet({blob:file,name:file.name,type:file.type,updated:Date.now()});await showRules();e.target.value=''};
document.getElementById('resetRules').onclick=async()=>{if(confirm('Ripristinare il regolamento Commander Armies 6.1 incluso nell’app?')){await rulesDelete();await showRules()}};